BEGIN TRANSACTION;
CREATE TABLE `AwardTypes` (  `awardtypeid` INTEGER PRIMARY KEY,   `awardtype` VARCHAR(15) NOT NULL);
CREATE TABLE `Awards` (  `awardid` INTEGER PRIMARY KEY,   `awardname` VARCHAR(100) NOT NULL,   `awardtypeid` INTEGER NOT NULL DEFAULT 1,   `classid` INTEGER,   `rankid` INTEGER,   `racerid` INTEGER DEFAULT 0,   `sort` INTEGER DEFAULT 0);
CREATE TABLE `BallotAwards` ( ballotid INTEGER NOT NULL, awardid INTEGER NOT NULL,  depth INTEGER NOT NULL);
CREATE TABLE CheckinAudit	(	seq    INTEGER PRIMARY KEY,	stmt   VARCHAR (250),	tstamp DATETIME	);
CREATE TABLE `Classes` (  `classid` INTEGER PRIMARY KEY,   `class` VARCHAR(75) NOT NULL UNIQUE COLLATE NOCASE,  `constituents` VARCHAR(100) DEFAULT '',  `rankids` VARCHAR(100) DEFAULT '', `durable` INTEGER, `ntrophies` INTEGER DEFAULT -1,  `sortorder` INTEGER);
CREATE TABLE ConstituentClasses (  antecedent INTEGER,  dependent  INTEGER,  UNIQUE (antecedent, dependent));
CREATE TABLE EventLaneDetails (  tresultid           INTEGER PRIMARY KEY,   finishid            INTEGER,   `lane`              INTEGER NOT NULL,   `finishtime`        DOUBLE NULL,   `finishplace`       INTEGER,   `completed`         TIMESTAMP DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE Events (  seq     INTEGER PRIMARY KEY,	tstamp  DATETIME,	action  INTEGER,  racerid INTEGER,  classid INTEGER,  rankid  INTEGER,  roundid INTEGER,  heat    INTEGER,  finishid  INTEGER,  other   VARCHAR(250)	);
CREATE TABLE Kiosks ( address VARCHAR(50), name VARCHAR(200), page VARCHAR(200), last_contact INTEGER NOT NULL);
CREATE TABLE MessageQueue (  msgid      INTEGER PRIMARY KEY,   recipient  VARCHAR(50),  expiration INTEGER,  message    TEXT  );
CREATE TABLE Partitions (  partitionid        INTEGER PRIMARY KEY,  name              VARCHAR(200) UNIQUE,  rankid            INTEGER,  sortorder         INTEGER);
CREATE TABLE Playlist (  queueid              INTEGER PRIMARY KEY,  seq                  INTEGER,  classid              INTEGER,  round                INTEGER,  bucket_limit         INTEGER,  bucketed             INTEGER,  n_times_per_lane     INTEGER,  sceneid_at_finish    INTEGER,  continue_racing      INTEGER  );
CREATE TABLE `RaceChart` (  `resultid` INTEGER PRIMARY KEY,   `classid` INTEGER,   `roundid` INTEGER NOT NULL,   `heat` INTEGER NOT NULL,   `lane` INTEGER NOT NULL,   `racerid` INTEGER,   `chartnumber` INTEGER,   `finishtime` DOUBLE NULL,   `finishplace` INTEGER,   `points` INTEGER,   `completed` TIMESTAMP,   `ignoretime` TINYINT(1) DEFAULT 0,   `masterheat` INTEGER DEFAULT 0);
CREATE TABLE `RaceInfo` (  `raceinfoid` INTEGER PRIMARY KEY,   `itemkey` VARCHAR(20) NOT NULL,   `itemvalue` VARCHAR(200));
CREATE TABLE `Ranks` (  `rankid` INTEGER PRIMARY KEY,   `rank` VARCHAR(75) NOT NULL COLLATE NOCASE,   `classid` INTEGER NOT NULL,  `sortorder` INTEGER );
CREATE TABLE `RegistrationInfo` (  `racerid` INTEGER PRIMARY KEY,   `carnumber` INTEGER NOT NULL,   `carname` VARCHAR(30),   `lastname` VARCHAR(30) NOT NULL COLLATE NOCASE,   `firstname` VARCHAR(30) NOT NULL COLLATE NOCASE,   `classid` INTEGER NOT NULL,   `rankid` INTEGER NOT NULL,   `partitionid` INTEGER NOT NULL,  `passedinspection` TINYINT(1) DEFAULT 0,   `imagefile` VARCHAR(255),   `carphoto` VARCHAR(255),   `note` VARCHAR(255),   `exclude` TINYINT(1) DEFAULT 0);
CREATE TABLE `Roster` (  `rosterid` INTEGER PRIMARY KEY,   `roundid` INTEGER NOT NULL,   `classid` INTEGER NOT NULL DEFAULT 0,   `racerid` INTEGER NOT NULL,   `finalist` TINYINT(1) DEFAULT 0,   `grandfinalist` TINYINT(1) DEFAULT 0);
CREATE TABLE `Rounds` (  `roundid` INTEGER PRIMARY KEY,   `round` INTEGER NOT NULL,   `classid` INTEGER NOT NULL,   `charttype` INTEGER,   `phase` INTEGER);
CREATE TABLE SceneKiosk ( scenekioskid INTEGER PRIMARY KEY, sceneid INTEGER, kiosk_name VARCHAR(200), page VARCHAR(200));
CREATE TABLE Scenes ( sceneid INTEGER PRIMARY KEY, name VARCHAR(200), sortorder INTEGER);
CREATE TABLE TimerSettings (  settingid            INTEGER PRIMARY KEY,  kind                 VARCHAR(20),  key                  VARCHAR(100),  type                 VARCHAR(10),  value                VARCHAR(100),  description          VARCHAR(500),  pending              VARCHAR(100)  );
CREATE TABLE `Voters` ( voterid INTEGER PRIMARY KEY,  ballotid INTEGER NOT NULL,  identifier VARCHAR(200),  when_cast TIMESTAMP,  ip_addr VARCHAR(200));
CREATE TABLE `Votes` ( voteid INTEGER PRIMARY KEY, awardid INTEGER NOT NULL,  racerid INTEGER NOT NULL,  voterid INTEGER NOT NULL);
CREATE INDEX Awards_awardtypeid ON Awards(awardtypeid);
CREATE INDEX Awards_awardname ON Awards(awardname);
CREATE INDEX Awards_classid ON Awards(classid);
CREATE INDEX Awards_rankid ON Awards(rankid);
CREATE INDEX Awards_sort ON Awards(sort);
CREATE INDEX RaceChart_chartnumber ON RaceChart(chartnumber);
CREATE INDEX RaceChart_classid ON RaceChart(classid);
CREATE INDEX RaceChart_finishtime ON RaceChart(finishtime);
CREATE INDEX RaceChart_heat ON RaceChart(heat);
CREATE INDEX RaceChart_lane ON RaceChart(lane);
CREATE INDEX RaceChart_masterheat ON RaceChart(masterheat);
CREATE INDEX RaceChart_points ON RaceChart(points);
CREATE INDEX RaceChart_racerid ON RaceChart(racerid);
CREATE INDEX RaceChart_roundid ON RaceChart(roundid);
CREATE INDEX RaceInfo_itemkey ON RaceInfo(itemkey);
CREATE INDEX Ranks_classid ON Ranks(classid);
CREATE INDEX Ranks_rank ON Ranks(rank);
CREATE INDEX RegistrationInfo_carnumber ON RegistrationInfo(carnumber);
CREATE INDEX RegistrationInfo_classid ON RegistrationInfo(classid);
CREATE INDEX RegistrationInfo_exclude ON RegistrationInfo(exclude);
CREATE INDEX RegistrationInfo_lastname ON RegistrationInfo(lastname);
CREATE INDEX RegistrationInfo_passedinspection ON RegistrationInfo(passedinspection);
CREATE INDEX RegistrationInfo_rankid ON RegistrationInfo(rankid);
CREATE INDEX Roster_classid ON Roster(classid);
CREATE INDEX Roster_racerid ON Roster(racerid);
CREATE INDEX Roster_roundid ON Roster(roundid);
CREATE INDEX Rounds_classid ON Rounds(classid);
CREATE INDEX Rounds_round ON Rounds(round);
CREATE INDEX SceneKiosk_primary ON SceneKiosk(sceneid, kiosk_name);
CREATE UNIQUE INDEX BallotAwards_Primary ON BallotAwards(ballotid, awardid);
CREATE INDEX BallotAwards_ballotid ON BallotAwards(ballotid);
CREATE INDEX BallotAwards_awardid ON BallotAwards(awardid);
CREATE INDEX Voters_identifier ON Voters(identifier);
CREATE INDEX Votes_awardid ON Votes(awardid);
CREATE INDEX Votes_racerid ON Votes(racerid);
CREATE INDEX Votes_voterid ON Votes(voterid);
CREATE INDEX EventLaneDetails_finishid ON EventLaneDetails(finishid);
COMMIT;
